import itertools

def get_min_diff(S):
    min_diff = float('inf')
    for combo in itertools.permutations(S, 4):
        e, f, g, h = combo
        diff = abs(e/h - g/f)
        if diff < min_diff:
            min_diff = diff
    return min_diff

print(get_min_diff([2, 3, 5, 7, 11]))
